actor Breaker {
    enum State { case closed, open(until: ContinuousClock.Instant), halfOpen }
    private var state = State.closed, trials = 0

    func admit() -> Bool {                      // atomic: no awaits inside
        switch state {
        case .closed: return true
        case .open(let until) where ContinuousClock.now >= until:
            state = .halfOpen; trials = 0; return true
        case .halfOpen: return trials < 3
        }
    }
}
